// plugins/withoutPushEntitlement.js
// O expo-notifications adiciona a capacidade de push (aps-environment) no iOS.
// Um app que só usa notificações locais não precisa dela, e a conta Apple
// gratuita não consegue assinar apps com push: o plugin remove a entrada.
const { withEntitlementsPlist } = require('expo/config-plugins');

module.exports = function withoutPushEntitlement(config) {
  return withEntitlementsPlist(config, (cfg) => {
    delete cfg.modResults['aps-environment'];
    return cfg;
  });
};

