import {
  GoogleSignin,
  isErrorWithCode,
  isSuccessResponse,
  statusCodes,
} from '@react-native-google-signin/google-signin';

// Uma vez, na abertura do app. O webClientId (cliente "Web" no Google Cloud)
// faz o Google emitir um idToken que o backend consegue validar.
GoogleSignin.configure({ webClientId: process.env.EXPO_PUBLIC_GOOGLE_WEB_CLIENT_ID });

export async function entrarComGoogle() {
  try {
    await GoogleSignin.hasPlayServices(); // Android: confere o Google Play Services
    const res = await GoogleSignin.signIn();
    if (!isSuccessResponse(res) || !res.data.idToken) return null; // cancelou

    // O backend valida o idToken com o Google e cria a sessão do app
    return api.post('/auth/google', { idToken: res.data.idToken });
  } catch (e) {
    if (isErrorWithCode(e) && e.code === statusCodes.IN_PROGRESS) return null;
    throw e; // DEVELOPER_ERROR costuma ser SHA-1 ou client ID errado
  }
}

import Constants from 'expo-constants';
import * as Device from 'expo-device';
import * as Notifications from 'expo-notifications';
import { Platform } from 'react-native';

export async function registrarPush(): Promise<string | null> {
  if (!Device.isDevice) return null; // push precisa de aparelho de verdade

  if (Platform.OS === 'android') {
    // Android 8+: toda notificação pertence a um canal
    await Notifications.setNotificationChannelAsync('pedidos', {
      name: 'Status do pedido',
      importance: Notifications.AndroidImportance.HIGH,
    });
  }

  let { status } = await Notifications.getPermissionsAsync();
  if (status !== 'granted') ({ status } = await Notifications.requestPermissionsAsync());
  if (status !== 'granted') return null;

  const projectId = Constants.expoConfig?.extra?.eas?.projectId;
  const { data: token } = await Notifications.getExpoPushTokenAsync({ projectId });
  await api.post('/push-tokens', { token, platform: Platform.OS }); // o backend envia os pushes
  return token;
}

