import CoreNFC
import ExpoModulesCore

public class LeitorNfcModule: Module {
  public func definition() -> ModuleDefinition {
    Name("LeitorNfc")

    // Síncrona: volta na hora para o JavaScript
    Function("disponivel") { () -> Bool in
      return NFCNDEFReaderSession.readingAvailable
    }

    // Assíncrona: vira uma Promise no JavaScript
    AsyncFunction("lerCartao") { (promise: Promise) in
      self.iniciarLeitura(promise)
    }

    // Eventos que o JavaScript pode escutar
    Events("onTagLida")
  }
}

// O Kotlin (android/.../LeitorNfcModule.kt) usa a mesma DSL:
