// modules/leitor-nfc/index.ts
import { requireNativeModule, type EventSubscription } from 'expo-modules-core';

type LeitorNfc = {
  disponivel(): boolean;
  lerCartao(): Promise<{ id: string }>;
  addListener(evento: 'onTagLida', cb: (tag: { id: string }) => void): EventSubscription;
};

// Mesmo nome do Name("LeitorNfc") no Swift e no Kotlin
const Nativo = requireNativeModule<LeitorNfc>('LeitorNfc');

export const nfcDisponivel = () => Nativo.disponivel();
export const lerCartao = () => Nativo.lerCartao();

// Na tela
if (nfcDisponivel()) {
  const { id } = await lerCartao();
}
